<?php $courses=ref001_course_domain(); ?><section class="ref-courses" data-section="courses"><div class="ref-content"><header class="ref-courses__head"><span class="ref-kicker"># COURCES</span><h2 class="ref-bracket-title">未来につながる<strong>７</strong>つのコース</h2></header><div class="ref-courses__grid"><?php foreach($courses as $i=>$course): $n=$i+1; $desc=ref001_get("course_{$n}_description",$course['description']); $r1=ref001_get("course_{$n}_recommendation_1",$course['recommendations'][0]); $r2=ref001_get("course_{$n}_recommendation_2",$course['recommendations'][1]); ?><article class="ref-course" style="--course:<?php ref001_e($course['color']); ?>"><div class="ref-course__icon" data-icon="<?php ref001_e($course['icon']); ?>"></div><h3><?php ref001_e($course['title']); ?></h3><p class="ref-course__desc"><?php ref001_e($desc); ?></p><div class="ref-course__rec"><span class="ref-course__rec-label">こんな人にオススメ！</span><ul><li><?php ref001_e($r1); ?></li><li><?php ref001_e($r2); ?></li></ul></div></article><?php endforeach; ?></div></div></section>